  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: EventsEventsActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'day', label: 'Day' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'events', label: 'Events Created', from: 'events' },
    { key: 'capacity', label: 'Combined Event Capacity', from: 'events.capacity' },
    { key: 'chg', label: 'Events Created vs Previous', calc: 'change(events)' },
  ],

  remarks: [
    { if: 'events == 0', tone: 'watch', title: 'No events created', say: 'No events were created in {label}.' },
    { if: 'true', tone: 'neutral', title: 'Event activity', say: '{events} events were created with a combined capacity of {capacity}.' },
  ],

  headline: '{label}: {events} events created with a combined capacity of {capacity}.',

  // coming periods the report page adds after the history (see forecast.js)
